<?php

declare(strict_types=1);require_once __DIR__.'/../../includes/module-admin.php';require_once __DIR__.'/../../includes/backup.php';$pdo=cmsAdminModuleBoot('backups');$base='/admin/backups.php';$dir=cmsBackupDir();
if(isset($_GET['download'])){$name=basename((string)$_GET['download']);$path=$dir.'/'.$name;if(!preg_match('/^cms-[A-Za-z0-9-]+\.cmsbak$/',$name)||!is_file($path)){http_response_code(404);exit;}header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.$name.'"');header('Content-Length: '.filesize($path));readfile($path);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){cmsVerifyCsrf();$a=cmsStr($_POST['action']??'create',20);try{if($a==='create'){$n=cmsCreateBackup($pdo);cmsAudit('backup.create','backup',$n);cmsAdminRedirect($base,'تم إنشاء النسخة الاحتياطية.');}$name=basename(cmsStr($_POST['name']??'',180));$path=$dir.'/'.$name;if(!preg_match('/^cms-[A-Za-z0-9-]+\.cmsbak$/',$name)||!is_file($path))cmsAdminRedirect($base,'ملف غير صحيح.');if($a==='delete'){unlink($path);cmsAudit('backup.delete','backup',$name);cmsAdminRedirect($base,'تم حذف النسخة.');}if($a==='restore'){if((string)($_POST['confirm']??'')!=='RESTORE')cmsAdminRedirect($base,'اكتب RESTORE للتأكيد.');cmsRestoreBackup($pdo,$path);cmsAudit('backup.restore','backup',$name);cmsAdminRedirect($base,'تم الاسترجاع وإنشاء نسخة تلقائية قبل العملية.');}}catch(Throwable $e){error_log('[CMS backup] '.$e->getMessage());cmsAdminRedirect($base,'تعذر تنفيذ العملية. راجع مساحة التخزين والصلاحيات.');}}
$files=[];foreach(glob($dir.'/cms-*.cmsbak')?:[] as $p)$files[]=['name'=>basename($p),'size'=>filesize($p),'time'=>filemtime($p)];usort($files,fn($a,$b)=>$b['time']<=>$a['time']);cmsAdminHead('النسخ الاحتياطية');cmsAdminSidebar('backups');cmsAdminTopbar('النسخ الاحتياطية');?>
<div class="content"><?php if($m=cmsAdminMessage()):?><div class="alert"><?=cmsE($m)?></div><?php endif;?><section class="card"><form method="post"><?=cmsCsrfField()?><button class="btn primary" name="action" value="create">إنشاء نسخة الآن</button></form></section><section class="card" style="margin-top:18px"><div class="table-wrap"><table class="table"><thead><tr><th>الملف</th><th>الحجم</th><th>التاريخ</th><th>إجراء</th></tr></thead><tbody><?php foreach($files as $f):?><tr><td><code><?=cmsE($f['name'])?></code></td><td><?=number_format($f['size']/1024,1)?> KB</td><td><?=date('Y-m-d H:i',$f['time'])?></td><td><div class="actions"><a class="btn" href="?download=<?=rawurlencode($f['name'])?>">تحميل</a><form method="post"><?=cmsCsrfField()?><input type="hidden" name="name" value="<?=cmsE($f['name'])?>"><input name="confirm" placeholder="RESTORE"><button class="btn" name="action" value="restore" onclick="return confirm('سيتم استرجاع البيانات. هل أنت متأكد؟')">استرجاع</button><button class="btn danger" name="action" value="delete" onclick="return confirm('حذف النسخة؟')">حذف</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php if(!$files):?><div class="empty">لا توجد نسخ احتياطية بعد.</div><?php endif;?></section></div><?php cmsAdminEnd();
